-- The sheet's crews: a name (stored trimmed, at most once on its sheet: the app refuses a repeat with a message, the
-- index is the backstop) and a lead, a person of the sheet; and its members, each a person of the sheet at most once in
-- the crew and never its lead.
CREATE TABLE crew (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200) NOT NULL,
    lead_id   BIGINT       NOT NULL REFERENCES person (id)
);
CREATE UNIQUE INDEX crew_sheet_name ON crew (sheet_id, name);

CREATE TABLE crew_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    crew_id   BIGINT       NOT NULL REFERENCES crew (id),
    person_id BIGINT       NOT NULL REFERENCES person (id)
);
CREATE UNIQUE INDEX crew_member_crew_person ON crew_member (crew_id, person_id);

-- Snapshotted with the rest of the screen (see V40, V41).
CREATE TABLE hist.crew AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM crew t WHERE FALSE;
CREATE INDEX hist_crew_snapshot ON hist.crew (snapshot_id);
CREATE TABLE asof.crew AS SELECT * FROM crew WHERE FALSE;
CREATE TABLE hist.crew_member AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM crew_member t WHERE FALSE;
CREATE INDEX hist_crew_member_snapshot ON hist.crew_member (snapshot_id);
CREATE TABLE asof.crew_member AS SELECT * FROM crew_member WHERE FALSE;
 * tables (schema asof), its today standing at that date, and read by the app's own repositories.
 */
@Repository
public class SheetHistory {

    /** The tables the screen reads (a statement's figures among them), parents before children. */
    private static final List<String> TABLES = List.of("sheet", "person", "person_grade", "person_terms", "person_hold", "person_retirement",
            "person_patron", "person_alias", "person_snapshot", "person_watch", "statement", "claim", "claim_log", "claim_lock", "rate", "rate_version", "sheet_setting",
            "sheet_setting_from", "period", "period_person_total", "sheet_role", "sheet_delegation", "holiday", "claim_tag", "void_reason", "claim_comment", "claim_line", "claim_template",
            "pool", "pool_member", "plan", "plan_claim", "crew", "crew_member");

    private final JdbcTemplate jdbc;

    private final DataSource dataSource;

        }
    }

    /** The table's columns, as the live table lists them. */
    private static String columns(JdbcTemplate jdbc, String table) {
        return String.join(", ", jdbc.queryForList("SELECT column_name FROM information_schema.columns"
                + " WHERE table_schema = 'PUBLIC' AND table_name = ? ORDER BY ordinal_position", String.class,
                table.toUpperCase()));
    }

    /** The condition picking the sheet's rows of the table in the schema (the sheet id its one parameter). */
    private static String ofSheet(String table, String schema) {
        return switch (table) {
            case "sheet" -> "id = ?";
            case "person_grade", "person_terms", "person_hold", "person_retirement", "person_patron", "person_watch" ->
                "person_id IN (SELECT id FROM " + schema + ".person WHERE sheet_id = ?)";
            case "period_person_total" -> "period_id IN (SELECT id FROM " + schema + ".period WHERE sheet_id = ?)";
            default -> "sheet_id = ?";
        };
    }
}

